<?php
namespace App\Http\Controllers\Api\Teacher;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Schema};
use App\Http\Controllers\Controller;
class PortalController extends Controller {
 private function eligible($u){return $u instanceof User && $u->status && $u->school_id && $u->hasRole('Teacher') && DB::table('schools')->where('id',$u->school_id)->where('status',1)->exists();}
 public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string|max:255']);$u=User::where('email',$d['email'])->first();abort_unless($u && Hash::check($d['password'],$u->password) && $this->eligible($u),401,'Invalid credentials or teacher access.');return response()->json(['token'=>$u->createToken('teacher-mobile',['teacher'],now()->addDays(30))->plainTextToken,'token_type'=>'Bearer']);}
 private function user(Request $r){$u=$r->user();abort_unless($this->eligible($u) && $r->bearerToken() && $u->currentAccessToken() instanceof \Laravel\Sanctum\PersonalAccessToken && $u->tokenCan('teacher'),403);return $u;}
 private function table(Request $r,$t){$u=$this->user($r);abort_unless(Schema::hasTable($t),503,'Module not installed.');return DB::table($t)->where('school_id',$u->school_id);}
 private function own(Request $r,$t,$col='teacher_user_id'){return $this->table($r,$t)->where($col,$r->user()->id);}
 private function assignments(Request $r){return $this->own($r,'teacher_assignments')->where('status',1);}
 private function assignment(Request $r,$id,$class=false){$a=$this->assignments($r)->when($class,fn($q)=>$q->where('is_class_teacher',1))->where('id',$id)->first();abort_unless($a,404);return $a;}
 private function students(Request $r,$a){return $this->table($r,'student_enrollments')->where('academic_year_id',$a->academic_year_id)->where('school_class_id',$a->school_class_id)->where('section_id',$a->section_id)->where('is_current',1)->where('status',1);}
 private function studentIds(Request $r,$a,$ids){abort_unless($this->students($r,$a)->whereIn('id',$ids)->count()===count($ids),422,'Invalid enrollment IDs.');}
 private function ok($data=[]){return response()->json(['success'=>true,'data'=>$data]);}
 public function logout(Request $r){$this->user($r)->currentAccessToken()->delete();return $this->ok();}
 public function password(Request $r){$u=$this->user($r);$d=$r->validate(['current_password'=>'required|string','password'=>'required|string|min:8|max:72|confirmed']);abort_unless(Hash::check($d['current_password'],$u->password),422,'Incorrect password.');$u->password=Hash::make($d['password']);$u->save();$u->tokens()->delete();return $this->ok(['message'=>'Login again.']);}
 public function profile(Request $r){$u=$this->user($r);return $this->ok(['user'=>$u->only(['id','name','email','school_id']),'employee'=>$this->own($r,'erp_employees','user_id')->first(['id','employee_code','name','email','designation','department','image_path'])]);}
 public function dashboard(Request $r){return $this->ok(['assignments'=>$this->assignments($r)->count(),'pending_classwork'=>$this->own($r,'teacher_classworks')->where('approval_status','pending')->count(),'unread_messages'=>$this->own($r,'teacher_messages','recipient_user_id')->whereNull('read_at')->count()]);}
 public function classes(Request $r){return $this->ok($this->assignments($r)->get());}
 public function roster(Request $r,$assignment){$a=$this->assignment($r,$assignment);$ids=$this->students($r,$a)->get(['id','student_id','roll_no']);$students=$this->table($r,'students')->whereIn('id',$ids->pluck('student_id'))->get(['id','student_name','admission_no'])->keyBy('id');return $this->ok($ids->map(fn($e)=>['enrollment_id'=>$e->id,'roll_no'=>$e->roll_no,'student'=>$students->get($e->student_id)]));}
 public function attendance(Request $r,$assignment){$a=$this->assignment($r,$assignment,true);$d=$r->validate(['date'=>'nullable|date_format:Y-m-d','month'=>'nullable|date_format:Y-m']);$q=$this->table($r,'student_attendance_sessions')->where('academic_year_id',$a->academic_year_id)->where('section_id',$a->section_id)->where('school_class_id',$a->school_class_id);isset($d['month'])?$q->where('attendance_date','like',$d['month'].'%'):$q->where('attendance_date',$d['date']??now()->toDateString());return $this->ok($this->table($r,'student_attendances')->whereIn('attendance_session_id',$q->pluck('id'))->get());}
 public function saveAttendance(Request $r,$assignment){$a=$this->assignment($r,$assignment,true);$d=$r->validate(['date'=>'required|date_format:Y-m-d|before_or_equal:today','marks'=>'required|array','marks.*'=>'required|in:present,absent,late,leave,half_day']);$ids=array_keys($d['marks']);$this->studentIds($r,$a,$ids);abort_unless(count($ids)===$this->students($r,$a)->count(),422,'Submit all students.');DB::transaction(function()use($r,$a,$d){$key=['school_id'=>$a->school_id,'academic_year_id'=>$a->academic_year_id,'school_class_id'=>$a->school_class_id,'section_id'=>$a->section_id,'attendance_date'=>$d['date']];$s=DB::table('student_attendance_sessions')->where($key)->first();$id=$s?$s->id:DB::table('student_attendance_sessions')->insertGetId($key+['marked_by'=>$r->user()->id,'status'=>1,'created_at'=>now(),'updated_at'=>now()]);foreach($this->students($r,$a)->get() as $e){\App\Models\StudentAttendance::updateOrCreate(['attendance_session_id'=>$id,'student_id'=>$e->student_id],['school_id'=>$a->school_id,'student_enrollment_id'=>$e->id,'attendance_status'=>$d['marks'][$e->id]]);}});return $this->ok();}
 public function marks(Request $r,$id){$a=$this->own($r,'teacher_assessments')->where('id',$id)->first();abort_unless($a,404);$assignment=$this->assignment($r,$a->teacher_assignment_id);$q=DB::table('teacher_assessment_marks')->where('assessment_id',$id)->whereIn('student_enrollment_id',$this->students($r,$assignment)->pluck('id'));if($r->isMethod('get'))return $this->ok($q->get());$d=$r->validate(['marks'=>'required|array','marks.*'=>'nullable|numeric|min:0|max:'.$a->max_marks]);$this->studentIds($r,$assignment,array_keys($d['marks']));DB::transaction(function()use($d,$id){foreach($d['marks'] as $e=>$m)\App\Models\TeacherAssessmentMark::updateOrCreate(['assessment_id'=>$id,'student_enrollment_id'=>$e],['marks'=>$m]);});return $this->ok();}
 private const RESOURCES = [
 'classwork'=>['teacher_classworks','teacher_user_id',['teacher_assignment_id'=>'required|integer','work_date'=>'required|date_format:Y-m-d','title'=>'required|string|max:200','type'=>'required|in:classwork,homework,assignment','description'=>'required|string|max:10000','due_date'=>'nullable|date|after_or_equal:work_date'],['approval_status'=>'pending']],
 'assessments'=>['teacher_assessments','teacher_user_id',['teacher_assignment_id'=>'required|integer','term'=>'required|string|max:80','title'=>'required|string|max:160','assessment_date'=>'required|date','max_marks'=>'required|numeric|gt:0|lte:99999'],[]],
 'staff-leave'=>['teacher_staff_leave_requests','user_id',['start_date'=>'required|date_format:Y-m-d','end_date'=>'required|date_format:Y-m-d|after_or_equal:start_date','leave_type'=>'required|string|max:40','reason'=>'required|string|max:2000'],['status'=>'pending']],
 'attendance-changes'=>['teacher_staff_attendance_changes','user_id',['attendance_date'=>'required|date_format:Y-m-d|before_or_equal:today','requested_status'=>'required|in:present,absent,late,leave,half_day','reason'=>'required|string|max:2000'],['status'=>'pending']],
 'tickets'=>['teacher_support_tickets','created_by',['title'=>'required|string|max:150','description'=>'required|string|max:5000','priority'=>'required|in:low,medium,high'],['status'=>'open']],
 'inventory-requests'=>['teacher_inventory_requests','requested_by',['item_id'=>'required|integer','quantity'=>'required|integer|min:1','reason'=>'nullable|string|max:500'],['status'=>'pending']],
 'lesson-plans'=>['teacher_lesson_plans','teacher_user_id',['teacher_assignment_id'=>'required|integer','lesson_date'=>'required|date_format:Y-m-d','topic'=>'required|string|max:200','objectives'=>'required|string|max:10000','activities'=>'nullable|string|max:10000','homework'=>'nullable|string|max:10000'],['status'=>'draft']],
 'student-leaves'=>['teacher_student_leaves','requested_by',['teacher_assignment_id'=>'required|integer','student_enrollment_id'=>'required|integer','start_date'=>'required|date_format:Y-m-d','end_date'=>'required|date_format:Y-m-d|after_or_equal:start_date','reason'=>'required|string|max:2000'],['status'=>'pending']],
 'student-remarks'=>['teacher_student_remarks','teacher_user_id',['teacher_assignment_id'=>'required|integer','student_enrollment_id'=>'required|integer','category'=>'required|string|max:50','remark'=>'required|string|max:2000','remark_date'=>'required|date_format:Y-m-d'],[]],
 'health'=>['teacher_student_health_records','teacher_user_id',['teacher_assignment_id'=>'required|integer','student_enrollment_id'=>'required|integer','recorded_on'=>'required|date_format:Y-m-d','height_cm'=>'nullable|numeric|min:0|max:300','weight_kg'=>'nullable|numeric|min:0|max:500','blood_group'=>'nullable|string|max:10','notes'=>'nullable|string|max:2000'],[]],
 'term-remarks'=>['teacher_term_remarks','teacher_user_id',['teacher_assignment_id'=>'required|integer','student_enrollment_id'=>'required|integer','term'=>'required|string|max:80','remark'=>'required|string|max:5000'],[]],
 'investments'=>['teacher_investment_declarations','user_id',['financial_year'=>'required|string|max:20','category'=>'required|string|max:100','declared_amount'=>'required|numeric|min:0|max:99999999','description'=>'nullable|string|max:500'],['status'=>'pending']],
 'resignations'=>['teacher_resignation_requests','user_id',['requested_last_day'=>'required|date_format:Y-m-d|after_or_equal:today','reason'=>'required|string|max:2000'],['status'=>'pending']],
 ];
 public function resource(Request $r,$resource,$id=null){abort_unless(isset(self::RESOURCES[$resource]),404);[$table,$owner,$rules,$defaults]=self::RESOURCES[$resource];$q=$this->own($r,$table,$owner);if($r->isMethod('get')){if($id){$row=$q->where('id',$id)->first();abort_unless($row,404);return $this->ok($row);}return $this->ok($q->orderByDesc('id')->paginate(25));}if($id){abort_unless(in_array($resource,['classwork','lesson-plans']),405);$q->where('id',$id)->where($resource==='classwork'?'approval_status':'status',$resource==='classwork'?'pending':'draft');abort_unless($q->exists(),404);if($r->isMethod('delete')){$q->delete();return $this->ok();}}else abort_unless($r->isMethod('post'),405);$d=$r->validate($rules);if(isset($d['teacher_assignment_id'])){$a=$this->assignment($r,$d['teacher_assignment_id'],in_array($resource,['student-leaves','health']));if(isset($d['student_enrollment_id']))$this->studentIds($r,$a,[$d['student_enrollment_id']]);if(in_array($resource,['student-leaves','student-remarks','health']))unset($d['teacher_assignment_id']);if($resource==='student-leaves')$d['academic_year_id']=$a->academic_year_id;}if($resource==='inventory-requests')abort_unless($this->table($r,'teacher_inventory_items')->where('id',$d['item_id'])->exists(),422);if($id){$q->update($d+['updated_at'=>now()]);return $this->ok(['id'=>$id]);}$id=DB::table($table)->insertGetId($d+$defaults+['school_id'=>$r->user()->school_id,$owner=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'data'=>['id'=>$id]],201);}
 public function feed(Request $r,$feed){$map=['calendar'=>['school_calendar_events',null],'library'=>['teacher_library_books',null],'library-loans'=>['teacher_library_loans','borrower_user_id'],'staff-attendance'=>['teacher_staff_attendances','user_id'],'hr-attendance'=>['hr_daily_attendance','user_id'],'leave-balances'=>['teacher_leave_entitlements','user_id'],'performance'=>['teacher_performance_reviews','teacher_user_id'],'gallery'=>['teacher_gallery_images',null],'inventory'=>['teacher_inventory_items',null],'learning'=>['teacher_learning_resources',null],'instructions'=>['teacher_instructions',null],'announcements'=>['teacher_announcements',null],'timetable'=>['teacher_timetable_slots','teacher_user_id'],'substitutions'=>['teacher_substitutions','substitute_teacher_user_id'],'inbox'=>['teacher_messages','recipient_user_id'],'sent'=>['teacher_messages','sender_user_id'],'notices'=>['teacher_notices','created_by']];abort_unless(isset($map[$feed]),404);[$t,$owner]=$map[$feed];$q=$owner?$this->own($r,$t,$owner):$this->table($r,$t);if(in_array($feed,['learning','instructions','announcements']))$q->where('published',1);if($feed==='announcements')$q->where(fn($x)=>$x->whereNull('expires_on')->orWhere('expires_on','>=',now()->toDateString()));if(in_array($feed,['calendar','library','timetable']))$q->where('status',1);return $this->ok($q->orderByDesc('id')->paginate(25));}
 public function payslips(Request $r){$q=$this->own($r,'hr_payslips','user_id')->whereIn('payroll_run_id',$this->table($r,'hr_payroll_runs')->where('status','finalized')->pluck('id'));return $this->ok($q->orderByDesc('pay_month')->paginate(25));}
 public function send(Request $r){$u=$this->user($r);$d=$r->validate(['recipient_user_id'=>'required|integer','subject'=>'required|string|max:200','body'=>'required|string|max:10000']);abort_unless($this->table($r,'users')->where('id',$d['recipient_user_id'])->where('status',1)->exists(),422);return $this->ok(['id'=>DB::table('teacher_messages')->insertGetId($d+['school_id'=>$u->school_id,'sender_user_id'=>$u->id,'created_at'=>now(),'updated_at'=>now()])]);}
 public function period(Request $r,$assignment){$a=$this->assignment($r,$assignment);$q=$this->table($r,'teacher_period_attendance')->where('teacher_assignment_id',$a->id);if($r->isMethod('get'))return $this->ok($q->orderByDesc('attendance_date')->paginate(25));$d=$r->validate(['attendance_date'=>'required|date_format:Y-m-d|before_or_equal:today','period_number'=>'required|integer|min:1|max:20','statuses'=>'required|array|min:1','statuses.*'=>'required|in:present,absent,late,leave']);$this->studentIds($r,$a,array_keys($d['statuses']));DB::transaction(function()use($r,$a,$d){foreach($d['statuses'] as $id=>$status){$key=['school_id'=>$a->school_id,'teacher_assignment_id'=>$a->id,'student_enrollment_id'=>$id,'attendance_date'=>$d['attendance_date'],'period_number'=>$d['period_number']];$v=['academic_year_id'=>$a->academic_year_id,'attendance_status'=>$status,'marked_by'=>$r->user()->id,'updated_at'=>now()];$q=DB::table('teacher_period_attendance')->where($key);if($q->exists())$q->update($v);else DB::table('teacher_period_attendance')->insert($key+$v+['created_at'=>now()]);}});return $this->ok();}
}
